ALTER TABLE public.leads ADD COLUMN qualification_status text NOT NULL DEFAULT 'unreviewed' CHECK(qualification_status IN ('unreviewed','qualified','not_suitable','duplicate','spam','support_request')), ADD COLUMN contact_permission text NOT NULL DEFAULT 'unconfirmed' CHECK(contact_permission IN ('unconfirmed','permitted','declined')), ADD COLUMN handoff_status text NOT NULL DEFAULT 'marketing' CHECK(handoff_status IN ('marketing','ready','accepted','returned')), ADD COLUMN handoff_at timestamptz;
CREATE OR REPLACE FUNCTION public.guard_lead_handoff() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.handoff_status IN ('ready','accepted') AND (NEW.qualification_status <> 'qualified' OR NEW.contact_permission <> 'permitted' OR NEW.assigned_to IS NULL) THEN RAISE EXCEPTION 'A qualified lead, recorded contact permission and Sales owner are required'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_lead_handoff BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.guard_lead_handoff();